using Aspire.Hosting.Testing;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Quality;
using Microsoft.Extensions.AI.Evaluation.Reporting;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.VisualStudio.TestTools.UnitTesting;

namespace MyApp.Evals;

[TestClass]
public sealed class EvalTests
{
    private static DistributedApplicationTestingBuilder _appHost = null!;
    private static IChatClient _chatClient = null!;
    private static IChatClient _evaluatorClient = null!;
    private static ReportingConfiguration _reportingConfig = null!;

    [ClassInitialize]
    public static async Task Initialize(TestContext context)
    {
        _appHost = await DistributedApplicationTestingBuilder.CreateAsync<Projects.MyApp_AppHost>();
        await _appHost.BuildAsync();

        var app = await _appHost.StartAsync();
        _chatClient = app.Services.GetRequiredService<IChatClient>();

        // Use the same model as an evaluator (in production, use a stronger model)
        _evaluatorClient = app.Services.GetRequiredService<IChatClient>();

        _reportingConfig = new ReportingConfiguration(
            evaluators:
            [
                new CoherenceEvaluator(),
                new RelevanceEvaluator(),
                new FluencyEvaluator(),
                new GroundednessEvaluator()
            ],
            chatConfiguration: new ChatConfiguration(_evaluatorClient));
    }

    [ClassCleanup]
    public static async Task Cleanup()
    {
        if (_appHost is not null)
        {
            await _appHost.DisposeAsync();
        }
    }

    [TestMethod]
    public async Task Chat_responds_coherently_to_greeting()
    {
        await using var scenario = await _reportingConfig.CreateScenarioRunAsync(
            scenarioName: nameof(Chat_responds_coherently_to_greeting));

        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "Hello, how are you today?")
        };

        var response = await _chatClient.GetResponseAsync(messages);
        messages.Add(response.Message);

        await scenario.EvaluateAsync(messages);
        scenario.AssertAllMetricsPassed();
    }

    [TestMethod]
    public async Task Chat_answers_factual_question()
    {
        await using var scenario = await _reportingConfig.CreateScenarioRunAsync(
            scenarioName: nameof(Chat_answers_factual_question));

        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "What is the capital of France? Answer in one sentence.")
        };

        var response = await _chatClient.GetResponseAsync(messages);
        messages.Add(response.Message);

        await scenario.EvaluateAsync(messages);
        scenario.AssertAllMetricsPassed();

        Assert.IsTrue(
            response.Message.Text?.Contains("Paris", StringComparison.OrdinalIgnoreCase),
            "Expected the response to mention Paris.");
    }

    [TestMethod]
    public async Task Chat_follows_system_prompt_instructions()
    {
        await using var scenario = await _reportingConfig.CreateScenarioRunAsync(
            scenarioName: nameof(Chat_follows_system_prompt_instructions));

        var messages = new List<ChatMessage>
        {
            new(ChatRole.System, "You are a helpful assistant that always responds in exactly three bullet points."),
            new(ChatRole.User, "What are some benefits of exercise?")
        };

        var response = await _chatClient.GetResponseAsync(messages);
        messages.Add(response.Message);

        await scenario.EvaluateAsync(messages);
        scenario.AssertAllMetricsPassed();

        var bulletCount = response.Message.Text?
            .Split('\n', StringSplitOptions.RemoveEmptyEntries)
            .Count(line => line.TrimStart().StartsWith("- ") || line.TrimStart().StartsWith("• ") || line.TrimStart().StartsWith("* "));

        Assert.AreEqual(3, bulletCount,
            $"Expected exactly 3 bullet points but got {bulletCount}.");
    }

    [TestMethod]
    public async Task Chat_handles_multiturn_conversation()
    {
        await using var scenario = await _reportingConfig.CreateScenarioRunAsync(
            scenarioName: nameof(Chat_handles_multiturn_conversation));

        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "My name is Alice.")
        };

        var response1 = await _chatClient.GetResponseAsync(messages);
        messages.Add(response1.Message);

        messages.Add(new ChatMessage(ChatRole.User, "What is my name?"));

        var response2 = await _chatClient.GetResponseAsync(messages);
        messages.Add(response2.Message);

        await scenario.EvaluateAsync(messages);
        scenario.AssertAllMetricsPassed();

        Assert.IsTrue(
            response2.Message.Text?.Contains("Alice", StringComparison.OrdinalIgnoreCase),
            "Expected the model to recall the name 'Alice'.");
    }
}

